/* ---------- Agenda ---------- */
/* today's events on two columns that run the whole list: the times on the content's left edge, where the head's title
   starts, and the titles, details, people and prep notes after the bar. A row's hover fill reaches 6px out round its words */
.agx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* the last event's 8px of hover room makes up the foot, so its words sit 16px from the card's edge, as at the top and sides
   (Blueprint's rows keep the full foot) */
.agx.panel:not(.crm-cn){padding-bottom:var(--dm-s-2)}
:root:not([data-style="soft"],[data-style="clean"]) .agx.panel:not(.crm-cn):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){padding-bottom:var(--dm-s-4)}
.agx-h{display:flex;align-items:center;justify-content:space-between}
.agx-h>div{display:flex;flex-direction:column;font-size:13.5px}
.agx-h b{font-weight:500}
.agx-h .muted{font-size:12px}
.agx-list{display:flex;flex-direction:column;gap:var(--dm-s-1);position:relative}
.agx .agx-list{margin:0 -6px}
.agx-e{display:grid;grid-template-columns:52px 3px 1fr;gap:10px;padding:var(--dm-s-2) 6px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));text-align:left;width:100%;transition:background .2s,opacity .3s}
@media (hover:hover) and (pointer:fine){.agx-e:hover{background:var(--dm-row)}}
/* the open event needs no fill of its own: it sits on the panel's white and its prep notes show it is open */
.agx-e.open{background:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.agx-e.open:hover{background:var(--dm-surface)}}
/* a past event: its title steps down to muted and its bar fades, the text stays readable */
.agx-e.past .t b{color:var(--dm-muted)}.agx-e.past .bar{opacity:.5}
.agx-e .tm{font-size:12px;color:var(--dm-muted);padding-top:1px}
.agx-e .bar{border-radius:var(--dm-r-tiny,2px);background:var(--dm-accent-mark,var(--dm-accent))}
.agx-e .t{display:flex;flex-direction:column;font-size:13px;min-width:0}
.agx-e .t b{font-weight:500}
.agx-e .t span{font-size:12px;color:var(--dm-muted)}
/* the people side by side, never stacked over each other; each avatar keeps its own letter colour (white or dark ink) */
.agx-e .who{display:flex;gap:var(--dm-s-1);margin-top:6px}
.agx-e .who .av{width:20px;height:20px;font-size:8.5px}
.agx-prep{grid-column:3;font-size:12.5px;line-height:1.5;color:var(--dm-fg2);display:flex;flex-direction:column;gap:5px;padding-top:var(--dm-s-2)}
.agx-prep div{display:flex;gap:7px;align-items:flex-start}
.agx-prep svg{color:var(--dm-accent-fg,var(--dm-accent));margin-top:3px;flex:none}
/* now: the time as a grey chip in the times' column, then the accent line from the bars' column to the content's right edge,
   starting at a dot centred on the bars. Nothing sits under the chip. The dot breathes in opacity, never in a colour */
.agx-now{display:grid;grid-template-columns:52px 3px 1fr;gap:10px;align-items:center;margin:2px 0;padding:0 6px}
.agx-now .tag{justify-self:start}
.agx-now i{justify-self:center;width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent));animation:agnow 2s ease-in-out infinite}
.agx-now::after{content:"";grid-column:2/-1;grid-row:1;height:2px;margin-left:1px;background:var(--dm-accent-mark,var(--dm-accent));border-radius:1px}
.agx-now i{grid-column:2;grid-row:1;position:relative;z-index:1}
@keyframes agnow{50%{opacity:.4}}
@media (prefers-reduced-motion:reduce){.agx-now i{animation:none}}
.agx-join{margin-top:var(--dm-s-2);align-self:flex-start}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Join alone presses */
.agx:not(.crm-cn) :is(.ib,.pill):active{transform:none}
/* Clean (owner, 17 and 18 Nov): its content 16px in from every edge; the prep notes' sparks are the quiet grey, as the agent's
   marks are in Clean's other cards */
:root[data-style="clean"] .agx.panel:not(.crm-cn),:root [data-style="clean"] .agx.panel:not(.crm-cn),:root [data-style="clean"].agx.panel:not(.crm-cn){padding:16px}
:root[data-style="clean"] .agx-prep svg,:root [data-style="clean"] .agx-prep svg,:root [data-style="clean"].agx-prep svg{color:var(--dm-fg2)}
/* Clean (owner, 21 Nov: "same comment… no difference besides the corners, need to change a lot more"). Today and its date sit in an
   off-white head strip under a hairline. The now time is a Clean pill with a hairline, and the now line a crisp 1px line in
   the accent (white in dark). The rails are neutral; only the next event's is the accent. A past event steps down as a whole:
   its time, title and details in the muted grey, its rail and people at half strength. The people sit side by side, as in
   Soft. The agent's ✦ notes are a plain list under the event, on its words' column, with no card or fill (notes are plain
   text), the ✦ muted and even gaps between its lines. The events are rows under one gliding highlight (hoverGlide), the last one's 8px of
   hover room making up the card's foot, so its words sit 16px from it */
:root[data-style="clean"] .agx.panel:not(.crm-cn),:root [data-style="clean"] .agx.panel:not(.crm-cn),:root [data-style="clean"].agx.panel:not(.crm-cn){padding:0 16px 8px}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-h,:root [data-style="clean"] .agx:not(.crm-cn) .agx-h,:root [data-style="clean"].agx:not(.crm-cn) .agx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-e .bar,:root [data-style="clean"] .agx:not(.crm-cn) .agx-e .bar,:root [data-style="clean"].agx:not(.crm-cn) .agx-e .bar{width:2px;margin:0 .5px;border-radius:1px;background:var(--dm-rail)}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-now+.agx-e .bar,:root [data-style="clean"] .agx:not(.crm-cn) .agx-now+.agx-e .bar,:root [data-style="clean"].agx:not(.crm-cn) .agx-now+.agx-e .bar{background:var(--dm-accent-mark,var(--dm-accent))}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-e .tm,:root [data-style="clean"] .agx:not(.crm-cn) .agx-e .tm,:root [data-style="clean"].agx:not(.crm-cn) .agx-e .tm{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-e.past :is(.t b,.t span),:root [data-style="clean"] .agx:not(.crm-cn) .agx-e.past :is(.t b,.t span),:root [data-style="clean"].agx:not(.crm-cn) .agx-e.past :is(.t b,.t span){color:var(--dm-muted)}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-e.past :is(.bar,.who),:root [data-style="clean"] .agx:not(.crm-cn) .agx-e.past :is(.bar,.who),:root [data-style="clean"].agx:not(.crm-cn) .agx-e.past :is(.bar,.who){opacity:.5}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-now .tag,:root [data-style="clean"] .agx:not(.crm-cn) .agx-now .tag,:root [data-style="clean"].agx:not(.crm-cn) .agx-now .tag{height:22px;padding:0 8px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-line);color:var(--dm-fg2);font-size:11.5px;font-variant-numeric:tabular-nums}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-now::after,:root [data-style="clean"] .agx:not(.crm-cn) .agx-now::after,:root [data-style="clean"].agx:not(.crm-cn) .agx-now::after{height:1px;border-radius:0}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-now i,:root [data-style="clean"] .agx:not(.crm-cn) .agx-now i,:root [data-style="clean"].agx:not(.crm-cn) .agx-now i{width:6px;height:6px}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-e,:root [data-style="clean"] .agx:not(.crm-cn) .agx-e,:root [data-style="clean"].agx:not(.crm-cn) .agx-e{border-radius:10px;transition:background-color var(--dm-t-fast) var(--dm-ease),opacity .3s var(--dm-ease)}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-prep,:root [data-style="clean"] .agx:not(.crm-cn) .agx-prep,:root [data-style="clean"].agx:not(.crm-cn) .agx-prep{gap:6px;line-height:18px}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-prep div,:root [data-style="clean"] .agx:not(.crm-cn) .agx-prep div,:root [data-style="clean"].agx:not(.crm-cn) .agx-prep div{gap:8px}
:root[data-style="clean"] .agx:not(.crm-cn) .agx-prep svg,:root [data-style="clean"] .agx:not(.crm-cn) .agx-prep svg,:root [data-style="clean"].agx:not(.crm-cn) .agx-prep svg{color:var(--dm-muted);margin-top:2px}

DM.def('agenda', (r, c) => {
  // Clean's one hover: a highlight that glides from event to event (hoverGlide); the open one keeps its own
  c.offs.push(hoverGlide($('.agx-list', r), '.agx-e', { keep:'.open' }));
  const E = [
    ['9:00','Standup','15 min, Design team','b',[['MK','var(--dm-av-l)'],['JO','var(--dm-av-m)'],['AR','var(--dm-av-p)']],null,1],
    ['11:30','Agent demo','30 min, Zoom','y',[['SL','var(--dm-av-t)'],['MK','var(--dm-av-l)']],['Demo flow: pricing audit, then the token export','Sam asked about cost limits last time, the cap is now $5'],0],
    ['1:00','Pricing workshop','90 min, Room 4','p',[['JO','var(--dm-av-m)'],['AR','var(--dm-av-p)'],['DK','var(--dm-av-b)'],['MK','var(--dm-av-l)']],['Trial to paid is up 8.1 pts since Sep 18','Open question: show monthly price crossed out on mobile too?','3 frames ready to review in Figma'],0],
    ['4:00','1:1 with Maya','30 min','l',[['MK','var(--dm-av-l)']],['She wanted feedback on the checkout copy','Library publish is waiting on her approval'],0]
  ];
  const list = $('.agx-list', r);
  list.innerHTML = E.map((e, i) => `<button class="agx-e${e[6] ? ' past' : ''}" data-i="${i}"><span class="tm num">${e[0]}</span><span class="bar"></span><span class="t"><b>${e[1]}</b><span>${e[2]}</span><span class="who">${e[4].map(a => AV(a[0], a[1])).join('')}</span></span></button>`).join('');
  const rows = $$('.agx-e', list);
  rows[0].after(html('<div class="agx-now" role="separator" aria-label="Now, 10:42"><span class="tag num">10:42</span><i></i></div>'));
  stagger([...list.children], 60);
  // the card eases to its new height as an event's prep notes open or fold away (grow())
  c.offs.push(grow($('.agx', r)));
  rows.forEach((el, i) => el.onclick = () => {
    const open = el.classList.contains('open'); rows.forEach(x => { x.classList.remove('open'); $('.agx-prep', x)?.remove(); });
    if (open || !E[i][5]) return;
    el.classList.add('open');
    const p = html(`<div class="agx-prep">${E[i][5].map(t => `<div>${I('spark','xs')}<span>${t}</span></div>`).join('')}${i === 1 ? '<span class="pill accent sm agx-join">Join in 48 min</span>' : ''}</div>`);
    el.appendChild(p); stagger([...p.children], 60);
  });
  // the preview opens one meeting on its own, unless you take over first
  c.auto(1000, () => rows[2].click());
});
